		public static DataTable GetAllMobileNosForGivenOtherStaffUserID(int aiSchoolId, string asUserIds, int aiAcademicYearId)
		{
			string sFetchStatement = " SELECT	 0 as  StudentCount " +
			                         ",''as FullName " +
			                         ",OtherStaffId,OtherStaffName as NameWithoutDesignation " +
			                         ",OtherStaffName+' ('+Teacher_Designation_Name+')' as Name " +
			                         ",MobileNo as Mobile_Number" +
			                         ",UserId As ID " +
			                         ",FirstName " +
			                         ",Teacher_Designation_Name as Designation " +
			                         ",DesignationId " +
			                         "FROM " +
			                         " vw_BaseOtherStaffDetails " +
			                         " WHERE " +
			                         " SchoolId =" + aiSchoolId +
			                         " AND " +
			                         " Is_Deleted = 'N' " +
			                         " AND UserId IN (" + asUserIds + ")";
			using (var oSQLServerDbUtility = new SQLServerDbUtility())
				return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataTable(sFetchStatement);
		}

