		public static DataTable FetchSchoolWiseOtherStaffMasterDetails(int SchoolId, int aiAcademicYearId)
		{
            string sFetchStatement = "SELECT 0 as  StudentCount " +
                                     ",''as FullName " +
                                     ",OtherStaffId,OtherStaffName as NameWithoutDesignation " +
                                     ",OtherStaffName+' ('+Teacher_Designation_Name+')' as Name " +
                                     ",MobileNo as Mobile_Number" +
                                     ",UserId As ID " +
                                     ",FirstName " +
                                     ",Teacher_Designation_Name as Designation " +
                                     ",vw_BaseOtherStaffDetails.DesignationId " +
                                     ",SortOrder " +
                                     "FROM " +
                                     " vw_BaseOtherStaffDetails INNER JOIN User_Master " +
                                     " ON vw_BaseOtherStaffDetails.UserId = User_Master.User_Id" +
                                     " WHERE " +
                                     "SchoolId=" + SchoolId +
                                     " AND vw_BaseOtherStaffDetails.Is_Deleted = 'N'" +
                                     " AND IsConsideredForMessage = 1" +
                                     " ORDER BY SortOrder";

			using (var oSQLServerDbUtility = new SQLServerDbUtility())
				return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataTable(sFetchStatement);
		}

        /// <summary>
        /// This method is used to insert Multiple Supervisor.
        /// </summary>
        /// <param name="abCanPublishUnpublishExam"></param>
        /// <param name="aiAcademicYearId"></param>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiInsertedById"></param>
        /// <param name="asSupervisorDetails"></param>
        public void InsertMultipleSupervisor(int aiSchoolId, int aiAcademicYearId, int aiInsertedById, string asSupervisorDetails, bool abCanPublishUnpublishExam)
		{
			using (var oSQLServerDbUtility = new SQLServerDbUtility())
			{
				oSQLServerDbUtility.AddParameter("School_Id", aiSchoolId, SqlDbType.Int);
				oSQLServerDbUtility.AddParameter("Academic_Year_Id", aiAcademicYearId, SqlDbType.Int);
				oSQLServerDbUtility.AddParameter("Inserted_By_Id", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("CanPublishUnpublishExam", abCanPublishUnpublishExam, SqlDbType.Bit);
				oSQLServerDbUtility.AddParameter("SupervisorDetails", asSupervisorDetails, SqlDbType.Xml);
				oSQLServerDbUtility.ExecuteStoredProcedureOnServer("usp_AddMultpleSupervisorDetails");
			}
		}

